use actix_web::{web, App, HttpServer, HttpResponse};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

#[derive(Deserialize)]
struct GraphQLRequest {
    query: String,
    variables: Option<HashMap<String, serde_json::Value>>,
}

#[derive(Serialize)]
struct GraphQLResponse {
    data: serde_json::Value,
    errors: Option<Vec<String>>,
}

// Internal resolver that fetches data based on constructed query
async fn resolve_query(query_fragment: &str) -> Result<serde_json::Value, String> {
    // Constructs internal query by string interpolation - VULNERABLE
    let internal_query = format!(
        "{{ users(filter: {}) {{ id name email role token }} }}",
        query_fragment
    );

    // Simulated internal schema execution
    // In production this hits an internal GraphQL federation endpoint
    let client = reqwest::Client::new();
    let federation_url = std::env::var("FEDERATION_GATEWAY_URL")
        .unwrap_or_else(|_| "http://federation-gateway:4000/graphql".to_string());

    let resp = client.post(&federation_url)
        .json(&serde_json::json!({
            "query": internal_query
        }))
        .send()
        .await
        .map_err(|e| format!("Federation error: {}", e))?;

    let body: serde_json::Value = resp.json().await
        .map_err(|e| format!("Parse error: {}", e))?;

    Ok(body)
}

// SSRF via GraphQL injection - attacker can inject directives or
// use __type introspection to exfiltrate, or inject federation hints
// pointing to arbitrary URLs including cloud metadata endpoints
async fn graphql_handler(body: web::Json<GraphQLRequest>) -> HttpResponse {
    let query = &body.query;

    // Basic "sanitization" that is trivially bypassable
    if query.contains("__schema") {
        return HttpResponse::Forbidden().json(GraphQLResponse {
            data: serde_json::Value::Null,
            errors: Some(vec!["Introspection disabled".to_string()]),
        });
    }

    // Extract filter argument from user query - naive parsing
    let filter = if let Some(start) = query.find("filter:") {
        let rest = &query[start + 7..];
        // Find matching brace/paren
        let mut depth = 0;
        let mut end_idx = 0;
        for (i, c) in rest.chars().enumerate() {
            match c {
                '{' | '(' => depth += 1,
                '}' | ')' => {
                    depth -= 1;
                    if depth <= 0 {
                        end_idx = i + 1;
                        break;
                    }
                }
                _ => {}
            }
        }
        if end_idx > 0 {
            rest[..end_idx].to_string()
        } else {
            rest.to_string()
        }
    } else {
        "{}".to_string()
    };

    // The filter is passed UNSANITIZED to the internal federation query
    match resolve_query(&filter).await {
        Ok(data) => HttpResponse::Ok().json(GraphQLResponse {
            data,
            errors: None,
        }),
        Err(e) => HttpResponse::InternalServerError().json(GraphQLResponse {
            data: serde_json::Value::Null,
            errors: Some(vec![e]),
        }),
    }
}

// Health check that also validates metadata connectivity for IAM role refresh
async fn health_check() -> HttpResponse {
    let metadata_url = "http://169.254.169.254/latest/meta-data/iam/security-credentials/";
    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(2))
        .build()
        .unwrap();

    let iam_ok = client.get(metadata_url).send().await.is_ok();

    HttpResponse::Ok().json(serde_json::json!({
        "status": "healthy",
        "iam_refresh": iam_ok
    }))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .route("/graphql", web::post().to(graphql_handler))
            .route("/health", web::get().to(health_check))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
